def record(conn: sqlite3.Connection, readings: Iterable[Reading]) -> int:
    """Insert readings, ignoring ones already stored. Returns rows inserted."""
    rows = [
        (r.index, int(r.ts.timestamp()), r.value, r.rating) for r in readings
    ]
    if not rows:
        return 0
    with conn:
        cursor = conn.executemany(
            "INSERT OR IGNORE INTO readings (idx, ts, value, rating) VALUES (?, ?, ?, ?)",
            rows,
        )
    return cursor.rowcount

